#nullable enable // autogenerated

using UnityEngine;

namespace MVZ2Logic.Models
{
    public abstract class ModelComponent : MonoBehaviour, IModelComponent
    {
        public virtual void Init() { }
        public virtual void UpdateLogic() { }
        public virtual void UpdateFrame(float deltaTime) { }
        public virtual void OnPropertySet(string name, object? value) { }
        public virtual void OnTrigger(string name) { }
        public virtual void SaveToSerializable(SerializableModelData serializable) { }
        public virtual void LoadFromSerializable(SerializableModelData serializable) { }
        protected Vector3 Lawn2TransPosition(Vector3 pos)
        {
            return Global.Level.LawnToTrans(pos);
        }
        protected Vector3 Trans2LawnPosition(Vector3 pos)
        {
            return Global.Level.TransToLawn(pos);
        }
        protected Vector3 Lawn2TransScale(Vector3 scale)
        {
            return Global.Level.LawnToTransScale * scale;
        }
        protected Vector3 Trans2LawnScale(Vector3 scale)
        {
            return Global.Level.TransToLawnScale * scale;
        }
        protected virtual void OnEnable()
        {
#if UNITY_EDITOR
            if (Application.isPlaying)
                return;
            Model = GetComponentInParent<Model>();
            Init();
#endif
        }
        protected virtual void Update()
        {
#if UNITY_EDITOR
            if (Application.isPlaying)
                return;
            UpdateFrame(Time.deltaTime);
#endif
        }
        public Model Model { get; private set; } = null!;

        void IModelComponent.SetModel(Model model)
        {
            Model = model;
        }

        bool IModelComponent.IsEnabled()
        {
            return this && enabled;
        }
    }
}
